    personIdPushdown?: boolean | null
    personsArgMaxVersion?: QueriesSqlResponseHogQLQueryModifiersNullableFieldsPersonsArgMaxVersion
    personsJoinMode?: QueriesSqlResponseHogQLQueryModifiersNullableFieldsPersonsJoinMode
    personsOnEventsMode?: QueriesSqlResponseHogQLQueryModifiersNullableFieldsPersonsOnEventsMode
